public class InnerTableOptimizerTableOptimizerConfigurationFactory(Action<Humidifier.Glue.TableOptimizerTypes.TableOptimizerConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Glue.TableOptimizerTypes.TableOptimizerConfiguration>
{

    internal InnerTableOptimizerRetentionConfigurationFactory RetentionConfigurationFactory { get; set; }

    internal InnerTableOptimizerOrphanFileDeletionConfigurationFactory OrphanFileDeletionConfigurationFactory { get; set; }

    internal InnerTableOptimizerVpcConfigurationFactory VpcConfigurationFactory { get; set; }

    internal InnerTableOptimizerCompactionConfigurationFactory CompactionConfigurationFactory { get; set; }

    protected override Humidifier.Glue.TableOptimizerTypes.TableOptimizerConfiguration Create()
    {
        var tableOptimizerConfigurationResult = CreateTableOptimizerConfiguration();
        factoryAction?.Invoke(tableOptimizerConfigurationResult);

        return tableOptimizerConfigurationResult;
    }

    private Humidifier.Glue.TableOptimizerTypes.TableOptimizerConfiguration CreateTableOptimizerConfiguration()
    {
        var tableOptimizerConfigurationResult = new Humidifier.Glue.TableOptimizerTypes.TableOptimizerConfiguration();

        return tableOptimizerConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Glue.TableOptimizerTypes.TableOptimizerConfiguration result)
    {
        base.CreateChildren(result);

        result.RetentionConfiguration ??= RetentionConfigurationFactory?.Build();
        result.OrphanFileDeletionConfiguration ??= OrphanFileDeletionConfigurationFactory?.Build();
        result.VpcConfiguration ??= VpcConfigurationFactory?.Build();
        result.CompactionConfiguration ??= CompactionConfigurationFactory?.Build();
    }

} // End Of Class

